<?php declare(strict_types=1); require_once dirname(__DIR__,2).'/lib/tool-page.php'; $tool=['title'=>'Free WebP to PNG Converter Online','description'=>'Convert WebP images to PNG directly in your browser.','url'=>'https://smarttoolz.in/tools/webp-to-png/']; smarttoolz_tool_page_start($tool); ?><main class="tool-page"><section class="tool-intro"><span class="tool-kicker">WEBP TO PNG</span><h1>WebP to PNG Converter</h1><p>Convert a WebP image to a PNG file locally in your browser.</p></section><section class="tool-workspace"><div class="tool-panel"><label>WebP image<input id="f" type="file" accept="image/webp"></label><button id="go" class="tool-btn">Convert to PNG</button><p id="out"></p><a id="dl" class="tool-btn" hidden download="converted.png">Download PNG</a></div></section></main><script>(()=>{const $=id=>document.getElementById(id);$('go').onclick=()=>{let f=$('f').files[0];if(!f){$('out').textContent='Choose a WebP file.';return}let i=new Image(),u=URL.createObjectURL(f);i.onload=()=>{let c=document.createElement('canvas');c.width=i.width;c.height=i.height;c.getContext('2d').drawImage(i,0,0);c.toBlob(b=>{$('dl').href=URL.createObjectURL(b);$('dl').hidden=false;$('out').textContent='Conversion complete.'},'image/png')};i.src=u}})();</script><?php smarttoolz_tool_page_end(); ?>